    "保存失败，请稍后再试。": "Save failed. Try again later.",
    "充值后 {days} 天内可自助退款，退还未使用部分，扣除该笔付款的支付通道费；付款后 {free} 天内全额。": "Self-serve refunds are available for {days} days after top-up. Unused balance is returned minus that payment’s processing fee; full refund within {free} days of payment.",
    "充值后 {days} 天内可自助退款，退还未使用部分，扣除该笔付款的支付通道费；欧盟/英国 {free} 天内全额。": "Self-serve refunds are available for {days} days after top-up. Unused balance is returned minus that payment’s processing fee; full refund in the EU/UK within {free} days.",
    "充值的余额按调用 AI 时的真实 token 成本逐次精确扣除，OceanLeo 不加价、不抽成。详见": "Top-up balance is deducted exactly at the real token cost of each AI call. OceanLeo adds no markup and takes no cut. See",
    "充值的余额按调用 AI 时的真实成本逐次扣除，OceanLeo 不加价、不抽成。": "Top-up balance is deducted at the real cost of each AI call. OceanLeo adds no markup and takes no cut.",
