    "充值金额": "Top-up amount",
    "充后余额不能超过 {cap}，这次最多还能充 {room}": "Balance after top-up cannot exceed {cap}. You can add at most {room} this time",
    "先保存发票抬头和税号，再对已支付订单申请开票。申请会进入排队；平台不会立刻给出税票文件，要等电子税务局开出后才会更新。": "Save the invoice title and tax ID first, then request an invoice on a paid order. Requests queue; this site will not hand you a tax invoice file until the e-tax bureau issues it.",
    "到卡 {from}–{to} 个工作日，只能退回原支付方式。每笔充值只能退一次。": "Arrives on the card in {from}–{to} business days, and only back to the original payment method. Each top-up can be refunded once.",
