    "已退款 {net} 到原支付方式，{from}–{to} 个工作日到账。": "Refunded {net} to the original payment method. Arrives in {from}–{to} business days.",
    "当前不能充值": "Cannot top up now",
    "当前档位 {tier} · 单笔最多 {perOrder} · 充后余额最多 {cap} · 今天还能充 {left} 笔": "Current tier {tier} · max {perOrder} per payment · balance cap {cap} after top-up · {left} top-ups left today",
    "抬头和税号都填了才能申请；地址和邮箱可先空着保存草稿。": "Title and tax ID are required to request. Address and email can stay empty as a draft.",
