    "钱包余额为负（因退款/拒付），充值抵平后才能继续使用。": "Wallet balance is negative (from a refund/chargeback). Top up enough to clear it before you can keep using it.",
    "付款收据由 Stripe 作为收款商户出具，不是香港公司税票。": "Payment receipts are issued by Stripe as the merchant of record, not as a Hong Kong company tax invoice.",
    "保存发票抬头后，可对已支付订单申请开票；真正的数电票由公司在电子税务局开出，申请当下不会得到税票文件。": "After you save an invoice title, you can request invoicing on a paid order. The actual e-tax invoice is issued by the company in the e-tax bureau; the request itself does not give you a tax-invoice file.",
    "充值后你可以使用": "What you get",
    "按官方价按量计费，不加价": "Official model prices, billed as you go. No markup.",
    "余额是真钱，不过期、不按月作废": "Your balance is real money. It never expires and is not voided at month end.",
    "一次充值，全站所有编辑器通用": "One top-up works across every OceanLeo editor.",
    "数百个模型，按每次真实用量扣费": "Hundreds of models, billed only for what you actually use.",
    "60 天内可自助退还未用完的余额": "Self-serve refund of unused balance for 60 days after top-up.",
    "一次余额，OceanLeo 系列网站通用": "One balance works across the OceanLeo family of sites.",
    "这笔充值有拒付正在处理。剩余余额已冻结，暂停充值（{until}）。向发卡行撤回后会自动恢复。": "This top-up has a chargeback in progress. The remaining balance is held and top-ups are paused ({until}). They resume if you withdraw it with your card issuer.",
    "发卡行已裁定这笔拒付成立。暂停充值至 {until}。剩余余额已解冻，可以继续使用。": "The card issuer decided this chargeback against us. Top-ups are paused until {until}. The remaining balance is released and you can keep using it.",
    "近几笔充值几乎未使用就全额退款。暂停充值至 {until}。退款和余额不受影响。": "Several recent top-ups were refunded in full with almost no use. Top-ups are paused until {until}. Refunds and your balance are not affected.",
    "近 {window} 天内有 {n} 笔充值几乎未使用就全额退款。暂停充值至 {until}。退款和余额不受影响。": "In the last {window} days, {n} top-ups were refunded in full with almost no use. Top-ups are paused until {until}. Refunds and your balance are not affected.",
    "近 {window} 天内有 {n} 笔充值几乎未使用就全额退款。还能充值的次数已用完，暂停充值至 {until}。": "In the last {window} days, {n} top-ups were refunded in full with almost no use. The remaining top-up has been used, so top-ups are paused until {until}.",
    "近 {window} 天内有 {n} 笔充值几乎未使用就全额退款，接下来至 {until} 还能充值 {left} 次。": "In the last {window} days, {n} top-ups were refunded in full with almost no use. You can still top up {left} more time(s) until {until}.",
    "告诉我们哪里没做好": "Tell us what we got wrong",
    "拒付处理中：剩余余额已冻结，暂停充值。向发卡行撤回后，结案会自动恢复。": "Chargeback in progress: the remaining balance is held and top-ups are paused. If you withdraw it with your issuer, everything restores when the case closes.",
    "你上次付款用的卡暂不能用于充值（至 {until}），请换一张卡": "The card you last paid with cannot be used to top up until {until}. Please use a different card.",
    "你上次付款用的卡暂不能用于充值（不再可用），请换一张卡": "The card you last paid with can no longer be used to top up. Please use a different card.",
    "已原路全额退回（这张卡/账号暂不能充值）": "Refunded in full to the original method (this card or account cannot top up for now)",
    "因近期拒付被裁定为我们胜诉，{days} 天内按新账号额度充值，至 {until}。": "After a chargeback decided in our favour, you top up at new-account limits for {days} days, until {until}.",
    "结案前": "until the case closes",
    "不再可用": "no longer available",
