    "充值的余额按调用 AI 时的真实成本逐次扣除，OceanLeo 不加价、不抽成。": "Das Guthaben wird je KI-Aufruf zu den echten Kosten abgezogen. OceanLeo schlägt nichts auf und behält nichts ein.",
