    "充值金额": "Aufladebetrag",
    "充后余额不能超过 {cap}，这次最多还能充 {room}": "Das Guthaben danach darf {cap} nicht übersteigen. Diesmal höchstens noch {room}",
    "先保存发票抬头和税号，再对已支付订单申请开票。申请会进入排队；平台不会立刻给出税票文件，要等电子税务局开出后才会更新。": "Speichere zuerst Rechnungsname und Steuernummer, dann beantrage die Rechnung zu einem bezahlten Auftrag. Anträge kommen in die Warteschlange; eine Steuerrechnung erscheint erst, wenn das elektronische Finanzamt sie ausstellt.",
    "到卡 {from}–{to} 个工作日，只能退回原支付方式。每笔充值只能退一次。": "Auf der Karte in {from}–{to} Werktagen, nur zurück zum ursprünglichen Zahlweg. Jede Aufladung einmal erstattbar.",
    "单笔最多 {max}": "Höchstens {max} pro Zahlung",
