    "发票申请暂不可用。": "Rechnungsanträge sind gerade nicht möglich.",
    "因近期退款/拒付，180 天内额度收紧，至 {until}。": "Nach einer kürzlichen Erstattung/Chargeback sind die Limits 180 Tage enger, bis {until}.",
