    "保存失败，请稍后再试。": "No se pudo guardar. Inténtalo más tarde.",
    "充值后 {days} 天内可自助退款，退还未使用部分，扣除该笔付款的支付通道费；付款后 {free} 天内全额。": "Reembolso en autoservicio durante {days} días tras recargar. Se devuelve lo no usado menos la comisión de ese pago; importe íntegro en {free} días desde el pago.",
    "充值后 {days} 天内可自助退款，退还未使用部分，扣除该笔付款的支付通道费；欧盟/英国 {free} 天内全额。": "Reembolso en autoservicio durante {days} días tras recargar. Se devuelve lo no usado menos la comisión; en la UE/Reino Unido, íntegro en {free} días.",
    "充值的余额按调用 AI 时的真实 token 成本逐次精确扣除，OceanLeo 不加价、不抽成。详见": "El saldo se descuenta exactamente al coste real de tokens de cada llamada de IA. OceanLeo no añade margen ni comisión. Ver",
    "充值的余额按调用 AI 时的真实成本逐次扣除，OceanLeo 不加价、不抽成。": "El saldo se descuenta al coste real de cada llamada de IA. OceanLeo no añade margen ni comisión.",
