    "先保存发票抬头和税号，再对已支付订单申请开票。申请会进入排队；平台不会立刻给出税票文件，要等电子税务局开出后才会更新。": "Guarda primero la razón social y el NIF, luego pide factura de un pedido pagado. La solicitud entra en cola; el archivo fiscal no aparece hasta que lo emita la agencia electrónica.",
    "到卡 {from}–{to} 个工作日，只能退回原支付方式。每笔充值只能退一次。": "Llega a la tarjeta en {from}–{to} días laborables, solo al método original. Cada recarga se devuelve una vez.",
