    "海外卡款的付款收据由 Stripe 出具。点「查看收据」打开的是 Stripe 托管页，不是香港公司税票。": "Los recibos de tarjetas extranjeras los emite Stripe. «Ver recibo» abre una página de Stripe, no una factura fiscal de una empresa de Hong Kong.",
