    "邮箱（可选）": "Correo (opcional)",
    "钱包余额为负（因退款/拒付），充值抵平后才能继续使用。": "El saldo es negativo (por una devolución/contracargo). Recarga hasta saldarlo para seguir usándolo.",
    "付款收据由 Stripe 作为收款商户出具，不是香港公司税票。": "Los recibos de pago los emite Stripe como comercio titular, no como factura fiscal de una empresa de Hong Kong.",
    "保存发票抬头后，可对已支付订单申请开票；真正的数电票由公司在电子税务局开出，申请当下不会得到税票文件。": "Tras guardar la razón social, puedes pedir factura de un pedido pagado. La factura fiscal electrónica real la emite la empresa en la agencia electrónica; la solicitud no te entrega el archivo fiscal.",
    "充值后你可以使用": "Qué puedes usar tras recargar",
    "按官方价按量计费，不加价": "Precios oficiales del modelo, cobro por uso. Sin margen.",
    "余额是真钱，不过期、不按月作废": "El saldo es dinero real. No caduca ni se anula a fin de mes.",
    "一次充值，全站所有编辑器通用": "Una recarga vale en todos los editores de OceanLeo.",
    "数百个模型，按每次真实用量扣费": "Cientos de modelos, cobro solo por el uso real de cada vez.",
    "60 天内可自助退还未用完的余额": "Reembolso en autoservicio del saldo no usado durante 60 días.",
    "一次余额，OceanLeo 系列网站通用": "Un saldo funciona en todos los sitios de la familia OceanLeo.",
    "这笔充值有拒付正在处理。剩余余额已冻结，暂停充值（{until}）。向发卡行撤回后会自动恢复。": "Esta recarga tiene un contracargo en curso. El saldo restante está retenido y las recargas están en pausa ({until}). Se reanudan si lo retiras en tu banco.",
    "发卡行已裁定这笔拒付成立。暂停充值至 {until}。剩余余额已解冻，可以继续使用。": "El banco decidió este contracargo en tu favor. Las recargas están en pausa hasta {until}. El saldo restante está liberado y puedes usarlo.",
    "近几笔充值几乎未使用就全额退款。暂停充值至 {until}。退款和余额不受影响。": "Varias recargas recientes se devolvieron enteras casi sin uso. Las recargas están en pausa hasta {until}. Las devoluciones y el saldo no cambian.",
    "近 {window} 天内有 {n} 笔充值几乎未使用就全额退款。暂停充值至 {until}。退款和余额不受影响。": "En los últimos {window} días, {n} recargas se devolvieron enteras casi sin uso. Las recargas están en pausa hasta {until}. Las devoluciones y el saldo no cambian.",
    "近 {window} 天内有 {n} 笔充值几乎未使用就全额退款。还能充值的次数已用完，暂停充值至 {until}。": "En los últimos {window} días, {n} recargas se devolvieron enteras casi sin uso. Ya usaste la recarga restante, así que están en pausa hasta {until}.",
    "近 {window} 天内有 {n} 笔充值几乎未使用就全额退款，接下来至 {until} 还能充值 {left} 次。": "En los últimos {window} días, {n} recargas se devolvieron enteras casi sin uso. Hasta {until} aún puedes recargar {left} vez/veces.",
    "告诉我们哪里没做好": "Dinos qué no hicimos bien",
    "拒付处理中：剩余余额已冻结，暂停充值。向发卡行撤回后，结案会自动恢复。": "Contracargo en curso: el saldo restante está retenido y las recargas en pausa. Si lo retiras en el banco, se restablece al cerrarse el caso.",
    "你上次付款用的卡暂不能用于充值（至 {until}），请换一张卡": "La tarjeta del último pago no sirve para recargar hasta {until}. Usa otra tarjeta.",
    "你上次付款用的卡暂不能用于充值（不再可用），请换一张卡": "La tarjeta del último pago ya no sirve para recargar. Usa otra tarjeta.",
    "已原路全额退回（这张卡/账号暂不能充值）": "Devuelto entero por el mismo medio (esta tarjeta o cuenta no puede recargar por ahora)",
    "因近期拒付被裁定为我们胜诉，{days} 天内按新账号额度充值，至 {until}。": "Tras un contracargo a nuestro favor, recargas con límites de cuenta nueva {days} días, hasta {until}.",
