    "保存失败，请稍后再试。": "L’enregistrement a échoué. Réessayez plus tard.",
    "充值后 {days} 天内可自助退款，退还未使用部分，扣除该笔付款的支付通道费；付款后 {free} 天内全额。": "Remboursement en libre-service pendant {days} jours après la recharge. Le solde inutilisé revient moins les frais de ce paiement ; intégral sous {free} jours après paiement.",
    "充值后 {days} 天内可自助退款，退还未使用部分，扣除该笔付款的支付通道费；欧盟/英国 {free} 天内全额。": "Remboursement en libre-service pendant {days} jours après la recharge. Solde inutilisé moins les frais ; UE/Royaume-Uni : intégral sous {free} jours.",
    "充值的余额按调用 AI 时的真实 token 成本逐次精确扣除，OceanLeo 不加价、不抽成。详见": "Le solde est débité au coût réel des tokens de chaque appel IA. OceanLeo n’ajoute aucune marge. Voir",
    "充值的余额按调用 AI 时的真实成本逐次扣除，OceanLeo 不加价、不抽成。": "Le solde est débité au coût réel de chaque appel IA. OceanLeo n’ajoute aucune marge.",
    "充值订单": "Commandes de recharge",
    "充值金额": "Montant de la recharge",
    "充后余额不能超过 {cap}，这次最多还能充 {room}": "Après recharge le solde ne peut dépasser {cap}. Cette fois au plus {room}",
    "先保存发票抬头和税号，再对已支付订单申请开票。申请会进入排队；平台不会立刻给出税票文件，要等电子税务局开出后才会更新。": "Enregistrez d’abord l’intitulé et le n° fiscal, puis demandez une facture sur une commande payée. La demande est mise en file ; le fichier n’apparaît qu’après émission par l’administration électronique.",
    "到卡 {from}–{to} 个工作日，只能退回原支付方式。每笔充值只能退一次。": "Arrivée sur la carte en {from}–{to} jours ouvrés, uniquement vers le moyen d’origine. Une recharge = un remboursement.",
    "单笔最多 {max}": "Au plus {max} par paiement",
