    "发票抬头": "Intitulé de facture",
    "发票申请暂不可用。": "Les demandes de facture sont indisponibles.",
    "因近期退款/拒付，180 天内额度收紧，至 {until}。": "Après un remboursement/litige récent, le plafond se resserre 180 jours, jusqu’au {until}.",
