    "当前不能充值": "Recharge impossible pour le moment",
    "当前档位 {tier} · 单笔最多 {perOrder} · 充后余额最多 {cap} · 今天还能充 {left} 笔": "Palier {tier} · max {perOrder} par paiement · plafond {cap} · encore {left} recharges aujourd’hui",
    "抬头和税号都填了才能申请；地址和邮箱可先空着保存草稿。": "L’intitulé et le n° fiscal sont requis. Adresse et e-mail peuvent rester vides en brouillon.",
