    "法律主体以网关为准：{entity}。": "L’entité légale est celle indiquée par la passerelle : {entity}.",
    "海外卡款的付款收据由 Stripe 出具。点「查看收据」打开的是 Stripe 托管页，不是香港公司税票。": "Les reçus de cartes étrangères sont émis par Stripe. « Voir le reçu » ouvre une page Stripe, pas une facture fiscale hongkongaise.",
