    "退回原卡": "Retour vers la carte d’origine",
    "退款已受理，{net} 将退回原支付方式，到账后会更新。": "Remboursement accepté. {net} reviendra vers le moyen d’origine et s’actualisera à l’arrivée.",
    "退款政策": "Politique de remboursement",
    "退款金额": "Montant du remboursement",
    "退款金额（最多 {max}）": "Montant du remboursement (max {max})",
    "邮箱（可选）": "E-mail (facultatif)",
    "钱包余额为负（因退款/拒付），充值抵平后才能继续使用。": "Le solde est négatif (remboursement/litige). Rechargez assez pour le remettre à zéro avant de continuer.",
    "付款收据由 Stripe 作为收款商户出具，不是香港公司税票。": "Les reçus de paiement sont émis par Stripe en tant que commerçant enregistré, pas comme facture fiscale d’une société de Hong Kong.",
    "保存发票抬头后，可对已支付订单申请开票；真正的数电票由公司在电子税务局开出，申请当下不会得到税票文件。": "Après avoir enregistré l’intitulé, vous pouvez demander une facture sur une commande payée. La facture fiscale électronique réelle est émise par la société auprès de l’administration électronique ; la demande elle-même ne vous donne pas le fichier.",
    "充值后你可以使用": "Ce que vous pouvez utiliser après la recharge",
    "按官方价按量计费，不加价": "Prix officiels des modèles, facturation à l’usage. Aucune marge.",
    "余额是真钱，不过期、不按月作废": "Le solde est de l’argent réel. Il n’expire pas et n’est pas annulé en fin de mois.",
    "一次充值，全站所有编辑器通用": "Une recharge fonctionne dans tous les éditeurs OceanLeo.",
    "数百个模型，按每次真实用量扣费": "Des centaines de modèles, débit uniquement selon l’usage réel de chaque appel.",
    "60 天内可自助退还未用完的余额": "Remboursement en libre-service du solde inutilisé pendant 60 jours après la recharge.",
    "一次余额，OceanLeo 系列网站通用": "Un solde fonctionne sur tous les sites de la famille OceanLeo.",
    "这笔充值有拒付正在处理。剩余余额已冻结，暂停充值（{until}）。向发卡行撤回后会自动恢复。": "Ce rechargement a un litige en cours. Le solde restant est bloqué et les rechargements sont en pause ({until}). Ils reprennent si vous le retirez auprès de votre banque.",
    "发卡行已裁定这笔拒付成立。暂停充值至 {until}。剩余余额已解冻，可以继续使用。": "La banque a tranché ce litige contre nous. Les rechargements sont en pause jusqu’au {until}. Le solde restant est débloqué et reste utilisable.",
    "近几笔充值几乎未使用就全额退款。暂停充值至 {until}。退款和余额不受影响。": "Plusieurs rechargements récents ont été remboursés en entier presque sans usage. Les rechargements sont en pause jusqu’au {until}. Les remboursements et le solde ne changent pas.",
    "近 {window} 天内有 {n} 笔充值几乎未使用就全额退款。暂停充值至 {until}。退款和余额不受影响。": "Au cours des {window} derniers jours, {n} rechargements ont été remboursés en entier presque sans usage. Les rechargements sont en pause jusqu’au {until}. Les remboursements et le solde ne changent pas.",
    "近 {window} 天内有 {n} 笔充值几乎未使用就全额退款。还能充值的次数已用完，暂停充值至 {until}。": "Au cours des {window} derniers jours, {n} rechargements ont été remboursés en entier presque sans usage. Le rechargement restant a été utilisé, donc pause jusqu’au {until}.",
    "近 {window} 天内有 {n} 笔充值几乎未使用就全额退款，接下来至 {until} 还能充值 {left} 次。": "Au cours des {window} derniers jours, {n} rechargements ont été remboursés en entier presque sans usage. Vous pouvez encore recharger {left} fois jusqu’au {until}.",
    "告诉我们哪里没做好": "Dites-nous ce que nous n’avons pas bien fait",
    "拒付处理中：剩余余额已冻结，暂停充值。向发卡行撤回后，结案会自动恢复。": "Litige en cours : le solde restant est bloqué et les rechargements sont en pause. Si vous le retirez auprès de la banque, tout est rétabli à la clôture.",
    "你上次付款用的卡暂不能用于充值（至 {until}），请换一张卡": "La carte de votre dernier paiement ne peut pas servir à recharger jusqu’au {until}. Utilisez une autre carte.",
    "你上次付款用的卡暂不能用于充值（不再可用），请换一张卡": "La carte de votre dernier paiement ne peut plus servir à recharger. Utilisez une autre carte.",
    "已原路全额退回（这张卡/账号暂不能充值）": "Remboursé en entier par le même moyen (cette carte ou ce compte ne peut pas recharger pour le moment)",
