    "钱包余额为负（因退款/拒付），充值抵平后才能继续使用。": "O saldo está negativo (reembolso/contestação). Recarregue até zerar para continuar.",
    "付款收据由 Stripe 作为收款商户出具，不是香港公司税票。": "Os recibos de pagamento são emitidos pela Stripe como comerciante de registro, não como nota fiscal de uma empresa de Hong Kong.",
