    "这笔充值有拒付正在处理。剩余余额已冻结，暂停充值（{until}）。向发卡行撤回后会自动恢复。": "Esta recarga tem um chargeback em andamento. O saldo restante está retido e as recargas estão pausadas ({until}). Elas voltam se você retirar no banco emissor.",
    "发卡行已裁定这笔拒付成立。暂停充值至 {until}。剩余余额已解冻，可以继续使用。": "O banco decidiu este chargeback contra nós. As recargas ficam pausadas até {until}. O saldo restante foi liberado e você pode usar.",
    "近几笔充值几乎未使用就全额退款。暂停充值至 {until}。退款和余额不受影响。": "Várias recargas recentes foram reembolsadas por completo quase sem uso. As recargas ficam pausadas até {until}. Reembolsos e saldo não mudam.",
