    "近 {window} 天内有 {n} 笔充值几乎未使用就全额退款，接下来至 {until} 还能充值 {left} 次。": "Nos últimos {window} dias, {n} recargas foram reembolsadas por completo quase sem uso. Até {until} você ainda pode recarregar {left} vez(es).",
