    "充值后 {days} 天内可自助退款，退还未使用部分，扣除该笔付款的支付通道费；付款后 {free} 天内全额。": "Reembolso self-service durante {days} dias após carregar. Devolve o não usado menos a taxa desse pagamento; integral em {free} dias após o pagamento.",
    "充值后 {days} 天内可自助退款，退还未使用部分，扣除该笔付款的支付通道费；欧盟/英国 {free} 天内全额。": "Reembolso self-service durante {days} dias após carregar. Não usado menos a taxa; UE/Reino Unido integral em {free} dias.",
    "充值的余额按调用 AI 时的真实 token 成本逐次精确扣除，OceanLeo 不加价、不抽成。详见": "O saldo é debitado no custo real de tokens de cada chamada de IA. A OceanLeo não acrescenta margem. Ver",
    "充值的余额按调用 AI 时的真实成本逐次扣除，OceanLeo 不加价、不抽成。": "O saldo é debitado no custo real de cada chamada de IA. A OceanLeo não acrescenta margem.",
    "充值订单": "Encomendas de carregamento",
    "充值金额": "Montante do carregamento",
    "充后余额不能超过 {cap}，这次最多还能充 {room}": "Depois de carregar o saldo não pode passar de {cap}. Desta vez no máximo {room}",
    "先保存发票抬头和税号，再对已支付订单申请开票。申请会进入排队；平台不会立刻给出税票文件，要等电子税务局开出后才会更新。": "Guarde primeiro a razão social e o NIF, depois peça fatura de uma encomenda paga. O pedido entra na fila; o ficheiro fiscal só aparece quando a autoridade eletrónica o emitir.",
    "到卡 {from}–{to} 个工作日，只能退回原支付方式。每笔充值只能退一次。": "Chega ao cartão em {from}–{to} dias úteis, só no método original. Cada carregamento reembolsa uma vez.",
    "单笔最多 {max}": "No máximo {max} por pagamento",
