    "当前不能充值": "Não é possível carregar agora",
    "当前档位 {tier} · 单笔最多 {perOrder} · 充后余额最多 {cap} · 今天还能充 {left} 笔": "Nível {tier} · máx. {perOrder} por pagamento · teto {cap} · hoje restam {left} carregamentos",
    "抬头和税号都填了才能申请；地址和邮箱可先空着保存草稿。": "Razão social e NIF são obrigatórios para pedir. Morada e e-mail podem ficar vazios como rascunho.",
