    "支付 {cur}{amount}": "Pagar {cur}{amount}",
    "支付方式": "Método de pagamento",
    "支付由充值页上当时能点的通道处理，OceanLeo 不存储你的卡号。问题可联系": "O pagamento passa pelo canal que puder tocar no carregamento. A OceanLeo não guarda o número do cartão. Se houver problema, fale com",
