    "法律主体以网关为准：{entity}。": "A entidade legal é a que o gateway informar: {entity}.",
    "海外卡款的付款收据由 Stripe 出具。点「查看收据」打开的是 Stripe 托管页，不是香港公司税票。": "Recibos de cartão no estrangeiro saem da Stripe. «Ver recibo» abre uma página da Stripe, não uma fatura fiscal de uma empresa de Hong Kong.",
    "申请发票": "Pedir fatura",
    "申请失败，请稍后再试。": "O pedido falhou. Tente novamente mais tarde.",
