    "退款已受理，{net} 将退回原支付方式，到账后会更新。": "Reembolso aceite. {net} volta ao método original e atualiza ao cair.",
    "退款政策": "Política de reembolso",
    "退款金额": "Montante do reembolso",
    "退款金额（最多 {max}）": "Montante do reembolso (máx. {max})",
    "邮箱（可选）": "E-mail (opcional)",
    "钱包余额为负（因退款/拒付），充值抵平后才能继续使用。": "O saldo está negativo (reembolso/contestação). Carregue até saldar para continuar.",
    "付款收据由 Stripe 作为收款商户出具，不是香港公司税票。": "Os recibos de pagamento são emitidos pela Stripe como comerciante de registo, não como fatura fiscal de uma empresa de Hong Kong.",
    "保存发票抬头后，可对已支付订单申请开票；真正的数电票由公司在电子税务局开出，申请当下不会得到税票文件。": "Depois de guardar a razão social, pode pedir fatura de uma encomenda paga. A fatura fiscal eletrónica real é emitida pela empresa na autoridade eletrónica; o pedido em si não entrega o ficheiro.",
    "充值后你可以使用": "O que pode usar depois de carregar",
    "按官方价按量计费，不加价": "Preços oficiais dos modelos, faturação por utilização. Sem margem.",
    "余额是真钱，不过期、不按月作废": "O saldo é dinheiro a sério. Não caduca e não é anulado no fim do mês.",
    "一次充值，全站所有编辑器通用": "Um carregamento vale em todos os editores OceanLeo.",
    "数百个模型，按每次真实用量扣费": "Centenas de modelos, cobrança só pelo uso real de cada vez.",
    "60 天内可自助退还未用完的余额": "Reembolso self-service do saldo não usado durante 60 dias após carregar.",
    "一次余额，OceanLeo 系列网站通用": "Um saldo funciona em todos os sítios da família OceanLeo.",
    "这笔充值有拒付正在处理。剩余余额已冻结，暂停充值（{until}）。向发卡行撤回后会自动恢复。": "Esta recarga tem um chargeback em curso. O saldo restante está retido e as recargas estão em pausa ({until}). Retomam se o retirar junto do banco emissor.",
    "发卡行已裁定这笔拒付成立。暂停充值至 {until}。剩余余额已解冻，可以继续使用。": "O banco decidiu este chargeback contra nós. As recargas ficam em pausa até {until}. O saldo restante foi libertado e pode usá-lo.",
    "近几笔充值几乎未使用就全额退款。暂停充值至 {until}。退款和余额不受影响。": "Várias recargas recentes foram reembolsadas na totalidade quase sem uso. As recargas ficam em pausa até {until}. Reembolsos e saldo não mudam.",
    "近 {window} 天内有 {n} 笔充值几乎未使用就全额退款。暂停充值至 {until}。退款和余额不受影响。": "Nos últimos {window} dias, {n} recargas foram reembolsadas na totalidade quase sem uso. As recargas ficam em pausa até {until}. Reembolsos e saldo não mudam.",
    "近 {window} 天内有 {n} 笔充值几乎未使用就全额退款。还能充值的次数已用完，暂停充值至 {until}。": "Nos últimos {window} dias, {n} recargas foram reembolsadas na totalidade quase sem uso. A recarga restante já foi usada, por isso pausa até {until}.",
    "近 {window} 天内有 {n} 笔充值几乎未使用就全额退款，接下来至 {until} 还能充值 {left} 次。": "Nos últimos {window} dias, {n} recargas foram reembolsadas na totalidade quase sem uso. Até {until} ainda pode recarregar {left} vez/vezes.",
    "告诉我们哪里没做好": "Diga-nos o que não fizemos bem",
    "拒付处理中：剩余余额已冻结，暂停充值。向发卡行撤回后，结案会自动恢复。": "Chargeback em curso: o saldo restante está retido e as recargas em pausa. Se o retirar no banco, tudo é restabelecido no encerramento.",
    "你上次付款用的卡暂不能用于充值（至 {until}），请换一张卡": "O cartão do último pagamento não pode recarregar até {until}. Utilize outro cartão.",
    "你上次付款用的卡暂不能用于充值（不再可用），请换一张卡": "O cartão do último pagamento já não pode recarregar. Utilize outro cartão.",
    "已原路全额退回（这张卡/账号暂不能充值）": "Reembolsado na totalidade pelo mesmo meio (este cartão ou conta não pode recarregar por agora)",
    "因近期拒付被裁定为我们胜诉，{days} 天内按新账号额度充值，至 {until}。": "Após um chargeback a nosso favor, recarrega nos limites de conta nova durante {days} dias, até {until}.",
    "结案前": "até o caso encerrar",
    "不再可用": "já não disponível",
