    "充值的余额按调用 AI 时的真实 token 成本逐次精确扣除，OceanLeo 不加价、不抽成。详见": "Số dư nạp được trừ đúng chi phí token thật của mỗi lần gọi AI. OceanLeo không cộng giá, không ăn chia. Xem",
