    "先保存发票抬头和税号，再对已支付订单申请开票。申请会进入排队；平台不会立刻给出税票文件，要等电子税务局开出后才会更新。": "Hãy lưu tiêu đề hóa đơn và mã số thuế trước, rồi mới xin xuất hóa đơn cho đơn đã trả. Yêu cầu vào hàng chờ; nền tảng không đưa file thuế ngay, phải đợi cơ quan thuế điện tử phát hành.",
    "到卡 {from}–{to} 个工作日，只能退回原支付方式。每笔充值只能退一次。": "Về thẻ trong {from}–{to} ngày làm việc, chỉ về đúng kênh cũ. Mỗi lần nạp chỉ hoàn một lần.",
    "单笔最多 {max}": "Mỗi lần tối đa {max}",
