    "当前不能充值": "Hiện không nạp được",
    "当前档位 {tier} · 单笔最多 {perOrder} · 充后余额最多 {cap} · 今天还能充 {left} 笔": "Hạng {tier} · mỗi lần tối đa {perOrder} · số dư sau nạp tối đa {cap} · hôm nay còn {left} lần",
    "抬头和税号都填了才能申请；地址和邮箱可先空着保存草稿。": "Phải điền tiêu đề và mã số thuế mới xin được; địa chỉ và email có thể để trống bản nháp.",
    "抬头已保存": "Đã lưu tiêu đề",
