    "支付方式": "Cách thanh toán",
    "支付由充值页上当时能点的通道处理，OceanLeo 不存储你的卡号。问题可联系": "Thanh toán do kênh bạn bấm được trên trang nạp xử lý. OceanLeo không lưu số thẻ. Gặp vấn đề hãy liên hệ",
    "支付通道费不予退还": "Phí kênh thanh toán không hoàn",
    "支付通道返回异常，请稍后再试。": "Kênh thanh toán trả về lỗi. Hãy thử lại sau.",
    "收据与发票": "Biên lai và hóa đơn",
    "暂无可用的支付通道，请联系管理员配置后再试。": "Chưa có kênh thanh toán. Hãy nhờ quản trị cấu hình rồi thử lại.",
    "有过真实用量满 30 天后自动放宽。": "Có用量 thật đủ 30 ngày sẽ tự nới.",
