    "正在退款…": "Đang hoàn…",
    "法定期内全额退回，不扣费": "Trong thời hạn luật định hoàn đủ, không trừ phí",
    "法律主体以网关为准：{entity}。": "Pháp nhân lấy theo cổng: {entity}.",
    "海外卡款的付款收据由 Stripe 出具。点「查看收据」打开的是 Stripe 托管页，不是香港公司税票。": "Biên lai thẻ nước ngoài do Stripe cấp. «Xem biên lai» mở trang do Stripe giữ, không phải hóa đơn thuế công ty Hong Kong.",
    "申请发票": "Xin hóa đơn",
    "申请失败，请稍后再试。": "Xin thất bại. Hãy thử lại sau.",
