    "海外卡款的付款收据由 Stripe 出具。点「查看收据」打开的是 Stripe 托管页，不是香港公司税票。": "Yurt dışı kart makbuzlarını Stripe keser. «Makbuzu gör» Stripe sayfası açar, Hong Kong şirketinin vergi faturası değil.",
