    "付款收据由 Stripe 作为收款商户出具，不是香港公司税票。": "Ödeme makbuzlarını Stripe kayıtlı satıcı olarak keser; Hong Kong şirketinin vergi faturası değildir.",
    "保存发票抬头后，可对已支付订单申请开票；真正的数电票由公司在电子税务局开出，申请当下不会得到税票文件。": "Fatura unvanını kaydettikten sonra ödenmiş sipariş için fatura isteyebilirsiniz. Asıl e-vergi faturasını şirket elektronik vergi dairesinde keser; istek anında dosya gelmez.",
