    "按官方价按量计费，不加价": "Resmi model fiyatları, kullanıma göre. Zam yok.",
    "余额是真钱，不过期、不按月作废": "Bakiye gerçek para. Süresi dolmaz, ay sonunda geçersiz olmaz.",
