    "一次余额，OceanLeo 系列网站通用": "Bir bakiye OceanLeo ailesindeki tüm sitelerde geçerlidir.",
    "这笔充值有拒付正在处理。剩余余额已冻结，暂停充值（{until}）。向发卡行撤回后会自动恢复。": "Bu yüklemede devam eden bir chargeback var. Kalan bakiye donduruldu ve yükleme durdu ({until}). Kart bankanızda geri çekerseniz yeniden açılır.",
    "发卡行已裁定这笔拒付成立。暂停充值至 {until}。剩余余额已解冻，可以继续使用。": "Kart bankası bu chargeback’te bize karşı karar verdi. Yükleme {until} tarihine kadar durur. Kalan bakiye açıldı, kullanmaya devam edebilirsiniz.",
    "近几笔充值几乎未使用就全额退款。暂停充值至 {until}。退款和余额不受影响。": "Son yüklemeler neredeyse kullanılmadan tam iade edildi. Yükleme {until} tarihine kadar durur. İadeler ve bakiye etkilenmez.",
    "近 {window} 天内有 {n} 笔充值几乎未使用就全额退款。暂停充值至 {until}。退款和余额不受影响。": "Son {window} günde {n} yükleme neredeyse kullanılmadan tam iade edildi. Yükleme {until} tarihine kadar durur. İadeler ve bakiye etkilenmez.",
    "近 {window} 天内有 {n} 笔充值几乎未使用就全额退款。还能充值的次数已用完，暂停充值至 {until}。": "Son {window} günde {n} yükleme neredeyse kullanılmadan tam iade edildi. Kalan yükleme hakkı kullanıldı, {until} tarihine kadar durur.",
    "近 {window} 天内有 {n} 笔充值几乎未使用就全额退款，接下来至 {until} 还能充值 {left} 次。": "Son {window} günde {n} yükleme neredeyse kullanılmadan tam iade edildi. {until} tarihine kadar {left} kez daha yükleyebilirsiniz.",
    "告诉我们哪里没做好": "Neyi yanlış yaptığımızı söyleyin",
    "拒付处理中：剩余余额已冻结，暂停充值。向发卡行撤回后，结案会自动恢复。": "Chargeback sürüyor: kalan bakiye donduruldu, yükleme durdu. Bankada geri çekerseniz dosya kapanınca her şey geri gelir.",
    "你上次付款用的卡暂不能用于充值（至 {until}），请换一张卡": "Son ödemede kullandığınız kart {until} tarihine kadar yükleme için kullanılamaz. Başka kart kullanın.",
    "你上次付款用的卡暂不能用于充值（不再可用），请换一张卡": "Son ödemede kullandığınız kart artık yükleme için kullanılamaz. Başka kart kullanın.",
    "已原路全额退回（这张卡/账号暂不能充值）": "Aynı yolla tam iade edildi (bu kart/hesap şimdilik yükleme yapamaz)",
    "因近期拒付被裁定为我们胜诉，{days} 天内按新账号额度充值，至 {until}。": "Lehimize sonuçlanan bir chargeback’ten sonra {days} gün yeni hesap limitleriyle yüklersiniz, {until} tarihine kadar.",
