    "海外卡款的付款收据由 Stripe 出具。点「查看收据」打开的是 Stripe 托管页，不是香港公司税票。": "海外カードの領収書は Stripe が発行します。「領収書を見る」は Stripe のページであり、香港法人の税務請求書ではありません。",
