    "钱包余额为负（因退款/拒付），充值抵平后才能继续使用。": "ウォレット残高がマイナスです（返金/チャージバック）。使い続ける前にチャージで埋めてください。",
    "付款收据由 Stripe 作为收款商户出具，不是香港公司税票。": "支払い領収書は Stripe が決済事業者として発行します。香港法人の税務請求書ではありません。",
    "保存发票抬头后，可对已支付订单申请开票；真正的数电票由公司在电子税务局开出，申请当下不会得到税票文件。": "請求名義を保存したあと、支払済み注文に請求書を申請できます。本物の電子税務請求書は会社が電子税務当局で発行します。申請時点ではファイルは出ません。",
    "充值后你可以使用": "チャージ後に使えること",
    "按官方价按量计费，不加价": "公式のモデル価格、従量課金。上乗せなし。",
    "余额是真钱，不过期、不按月作废": "残高は本物のお金です。期限切れもなく、月末に失効しません。",
    "一次充值，全站所有编辑器通用": "一度のチャージで、すべての OceanLeo エディターで使えます。",
    "数百个模型，按每次真实用量扣费": "数百のモデル。毎回の実使用量だけを引きます。",
    "60 天内可自助退还未用完的余额": "チャージ後 60 日以内は、未使用残高をセルフ返金できます。",
    "一次余额，OceanLeo 系列网站通用": "ひとつの残高は、OceanLeo ファミリーのすべてのサイトで使えます。",
    "这笔充值有拒付正在处理。剩余余额已冻结，暂停充值（{until}）。向发卡行撤回后会自动恢复。": "このチャージはチャージバック審査中です。残額は凍結され、チャージは停止されます（{until}）。カード会社で取り下げると自動で戻ります。",
    "发卡行已裁定这笔拒付成立。暂停充值至 {until}。剩余余额已解冻，可以继续使用。": "カード会社がこのチャージバックをこちら敗訴としました。{until} までチャージできません。残額は解除済みで使えます。",
    "近几笔充值几乎未使用就全额退款。暂停充值至 {until}。退款和余额不受影响。": "最近のチャージがほとんど使われないまま全額返金されました。{until} までチャージ停止です。返金と残高はそのままです。",
    "近 {window} 天内有 {n} 笔充值几乎未使用就全额退款。暂停充值至 {until}。退款和余额不受影响。": "過去 {window} 日で {n} 件のチャージがほとんど使われないまま全額返金されました。{until} までチャージ停止です。返金と残高はそのままです。",
    "近 {window} 天内有 {n} 笔充值几乎未使用就全额退款。还能充值的次数已用完，暂停充值至 {until}。": "過去 {window} 日で {n} 件のチャージがほとんど使われないまま全額返金されました。残りのチャージ回数は使い切ったため、{until} まで停止です。",
    "近 {window} 天内有 {n} 笔充值几乎未使用就全额退款，接下来至 {until} 还能充值 {left} 次。": "過去 {window} 日で {n} 件のチャージがほとんど使われないまま全額返金されました。{until} まであと {left} 回チャージできます。",
    "告诉我们哪里没做好": "改善点を教えてください",
    "拒付处理中：剩余余额已冻结，暂停充值。向发卡行撤回后，结案会自动恢复。": "チャージバック処理中：残額は凍結、チャージは停止。カード会社で取り下げると、結審後に自動で戻ります。",
    "你上次付款用的卡暂不能用于充值（至 {until}），请换一张卡": "前回使ったカードは {until} までチャージに使えません。別のカードをご利用ください。",
    "你上次付款用的卡暂不能用于充值（不再可用），请换一张卡": "前回使ったカードはチャージに使えません。別のカードをご利用ください。",
    "已原路全额退回（这张卡/账号暂不能充值）": "元の方法へ全額返金済み（このカード／アカウントは当分チャージできません）",
    "因近期拒付被裁定为我们胜诉，{days} 天内按新账号额度充值，至 {until}。": "チャージバックが当方勝訴となったため、{days} 日間は新規アカウント枠でチャージします（{until} まで）。",
    "结案前": "結審まで",
    "不再可用": "利用不可",
