    "自助退款暂不可用，请联系 support。": "셀프 환불을 지금은 쓸 수 없습니다. support에 문의하세요.",
    "请先登录。": "먼저 로그인해 주세요.",
    "网络失败，请稍后再试。": "네트워크에 실패했습니다. 나중에 다시 시도하세요.",
    "退款失败，请稍后再试。": "환불에 실패했습니다. 나중에 다시 시도하세요.",
    "退款处理中": "환불 처리 중",
