    "下单失败，请稍后再试。": "주문에 실패했습니다. 나중에 다시 시도하세요.",
    "付款凭证随支付机构。": "결제 증빙은 결제사에서 나옵니다.",
    "保存失败，请稍后再试。": "저장에 실패했습니다. 나중에 다시 시도하세요.",
    "充值后 {days} 天内可自助退款，退还未使用部分，扣除该笔付款的支付通道费；付款后 {free} 天内全额。": "충전 후 {days}일 안에 셀프 환불할 수 있습니다. 쓰지 않은 금액에서 해당 결제의 수수료를 뺀 뒤 돌려줍니다. 결제 후 {free}일 안에는 전액입니다.",
