    "充值的余额按调用 AI 时的真实 token 成本逐次精确扣除，OceanLeo 不加价、不抽成。详见": "충전 잔액은 각 AI 호출의 실제 토큰 원가만큼 정확히 차감됩니다. OceanLeo는 가산이나 수수료를 붙이지 않습니다. 자세한 내용:",
    "充值的余额按调用 AI 时的真实成本逐次扣除，OceanLeo 不加价、不抽成。": "충전 잔액은 각 AI 호출의 실제 원가만큼 차감됩니다. OceanLeo는 가산이나 수수료를 붙이지 않습니다.",
    "充值订单": "충전 주문",
    "充值金额": "충전 금액",
    "充后余额不能超过 {cap}，这次最多还能充 {room}": "충전 후 잔액은 {cap}을(를) 넘을 수 없습니다. 이번에는 최대 {room}",
    "先保存发票抬头和税号，再对已支付订单申请开票。申请会进入排队；平台不会立刻给出税票文件，要等电子税务局开出后才会更新。": "먼저 세금계산서 상호와 납세번호를 저장한 뒤, 결제한 주문에 발행을 신청하세요. 신청은 대기열에 들어가며, 전자 세무 당국이 발급하기 전에는 파일이 나오지 않습니다.",
