    "海外卡款的付款收据由 Stripe 出具。点「查看收据」打开的是 Stripe 托管页，不是香港公司税票。": "해외 카드 영수증은 Stripe가 발행합니다. 「영수증 보기」는 Stripe 호스팅 페이지이며 홍콩 회사 세금계산서가 아닙니다.",
