    "充值后 {days} 天内可自助退款，退还未使用部分，扣除该笔付款的支付通道费；付款后 {free} 天内全额。": "يمكن الاسترداد الذاتي خلال {days} يومًا بعد الشحن. يُعاد غير المستخدم بعد خصم رسوم قناة تلك الدفعة؛ كامل المبلغ خلال {free} يومًا بعد الدفع.",
    "充值后 {days} 天内可自助退款，退还未使用部分，扣除该笔付款的支付通道费；欧盟/英国 {free} 天内全额。": "يمكن الاسترداد الذاتي خلال {days} يومًا بعد الشحن. يُعاد غير المستخدم بعد خصم الرسوم؛ في الاتحاد الأوروبي/المملكة المتحدة كامل خلال {free} يومًا.",
    "充值的余额按调用 AI 时的真实 token 成本逐次精确扣除，OceanLeo 不加价、不抽成。详见": "يُخصم رصيد الشحن بتكلفة التوكن الحقيقية لكل استدعاء ذكاء اصطناعي. OceanLeo لا يضيف هامشًا. انظر",
    "充值的余额按调用 AI 时的真实成本逐次扣除，OceanLeo 不加价、不抽成。": "يُخصم رصيد الشحن بالتكلفة الحقيقية لكل استدعاء ذكاء اصطناعي. OceanLeo لا يضيف هامشًا.",
