    "充后余额不能超过 {cap}，这次最多还能充 {room}": "بعد الشحن لا يجوز أن يتجاوز الرصيد {cap}. هذه المرة بحد أقصى {room}",
    "先保存发票抬头和税号，再对已支付订单申请开票。申请会进入排队；平台不会立刻给出税票文件，要等电子税务局开出后才会更新。": "احفظ عنوان الفاتورة والرقم الضريبي أولًا، ثم اطلب فاتورة لطلب مدفوع. يدخل الطلب قائمة الانتظار ولن يظهر ملف الضريبة حتى تصدره الهيئة الإلكترونية.",
    "到卡 {from}–{to} 个工作日，只能退回原支付方式。每笔充值只能退一次。": "يصل إلى البطاقة خلال {from}–{to} يوم عمل، وإلى وسيلة الدفع الأصلية فقط. كل شحن يُسترد مرة واحدة.",
