    "邮箱（可选）": "البريد (اختياري)",
    "钱包余额为负（因退款/拒付），充值抵平后才能继续使用。": "رصيد المحفظة سالب (بسبب استرداد/رد مبلغ). اشحن بما يكفي لتسويته قبل المتابعة.",
    "付款收据由 Stripe 作为收款商户出具，不是香港公司税票。": "إيصالات الدفع يصدرها Stripe كتاجر مسجّل، وليست فاتورة ضريبية لشركة في هونغ كونغ.",
    "保存发票抬头后，可对已支付订单申请开票；真正的数电票由公司在电子税务局开出，申请当下不会得到税票文件。": "بعد حفظ عنوان الفاتورة يمكنك طلب فاتورة لطلب مدفوع. الفاتورة الضريبية الإلكترونية الفعلية تصدرها الشركة في الهيئة الإلكترونية؛ الطلب نفسه لا يعطيك ملف الضريبة.",
    "充值后你可以使用": "ما يمكنك استخدامه بعد الشحن",
    "按官方价按量计费，不加价": "أسعار النماذج الرسمية، محاسبة حسب الاستخدام. بلا هامش.",
    "余额是真钱，不过期、不按月作废": "الرصيد مال حقيقي. لا ينتهي ولا يُلغى في نهاية الشهر.",
    "一次充值，全站所有编辑器通用": "شحنة واحدة تعمل في كل محررات OceanLeo.",
    "数百个模型，按每次真实用量扣费": "مئات النماذج، يُخصم فقط حسب الاستخدام الحقيقي في كل مرة.",
    "60 天内可自助退还未用完的余额": "استرداد ذاتي للرصيد غير المستخدم خلال 60 يومًا بعد الشحن.",
    "一次余额，OceanLeo 系列网站通用": "رصيد واحد يعمل في كل مواقع عائلة OceanLeo.",
    "这笔充值有拒付正在处理。剩余余额已冻结，暂停充值（{until}）。向发卡行撤回后会自动恢复。": "هذه التعبئة عليها اعتراض قيد المعالجة. الرصيد المتبقي مجمّد والشحن متوقف ({until}). يعود تلقائيًا إذا سحبت الاعتراض لدى البنك المصدر.",
    "发卡行已裁定这笔拒付成立。暂停充值至 {until}。剩余余额已解冻，可以继续使用。": "قرر البنك المصدر هذا الاعتراض ضدنا. الشحن متوقف حتى {until}. الرصيد المتبقي أُفرج عنه ويمكنك استخدامه.",
    "近几笔充值几乎未使用就全额退款。暂停充值至 {until}。退款和余额不受影响。": "أُرجعت تعبئات أخيرة بالكامل مع استخدام ضئيل. الشحن متوقف حتى {until}. الاسترداد والرصيد لا يتأثران.",
    "近 {window} 天内有 {n} 笔充值几乎未使用就全额退款。暂停充值至 {until}。退款和余额不受影响。": "خلال آخر {window} يومًا أُرجعت {n} تعبئات بالكامل مع استخدام ضئيل. الشحن متوقف حتى {until}. الاسترداد والرصيد لا يتأثران.",
    "近 {window} 天内有 {n} 笔充值几乎未使用就全额退款。还能充值的次数已用完，暂停充值至 {until}。": "خلال آخر {window} يومًا أُرجعت {n} تعبئات بالكامل مع استخدام ضئيل. استُنفدت التعبئة المتبقية لذا الشحن متوقف حتى {until}.",
    "近 {window} 天内有 {n} 笔充值几乎未使用就全额退款，接下来至 {until} 还能充值 {left} 次。": "خلال آخر {window} يومًا أُرجعت {n} تعبئات بالكامل مع استخدام ضئيل. يمكنك الشحن {left} مرة أخرى حتى {until}.",
    "告诉我们哪里没做好": "أخبرنا ما الذي لم نحسنه",
    "拒付处理中：剩余余额已冻结，暂停充值。向发卡行撤回后，结案会自动恢复。": "اعتراض قيد المعالجة: الرصيد المتبقي مجمّد والشحن متوقف. إذا سحبته لدى البنك يُستعاد كل شيء عند إغلاق القضية.",
    "你上次付款用的卡暂不能用于充值（至 {until}），请换一张卡": "البطاقة المستخدمة في آخر دفع لا تصلح للشحن حتى {until}. استخدم بطاقة أخرى.",
    "你上次付款用的卡暂不能用于充值（不再可用），请换一张卡": "البطاقة المستخدمة في آخر دفع لم تعد تصلح للشحن. استخدم بطاقة أخرى.",
    "已原路全额退回（这张卡/账号暂不能充值）": "أُعيد المبلغ بالكامل بنفس الطريق (هذه البطاقة/الحساب لا يمكنها الشحن الآن)",
    "因近期拒付被裁定为我们胜诉，{days} 天内按新账号额度充值，至 {until}。": "بعد اعتراض حُسم لصالحنا تشحن بحدود الحساب الجديد لمدة {days} يومًا حتى {until}.",
    "结案前": "حتى إغلاق القضية",
