    "充值的余额按调用 AI 时的真实 token 成本逐次精确扣除，OceanLeo 不加价、不抽成。详见": "ยอดเติมหักตามต้นทุนโทเคนจริงของการเรียก AI แต่ละครั้ง OceanLeo ไม่บวก ไม่หักส่วน ดู",
    "充值的余额按调用 AI 时的真实成本逐次扣除，OceanLeo 不加价、不抽成。": "ยอดเติมหักตามต้นทุนจริงของการเรียก AI แต่ละครั้ง OceanLeo ไม่บวก ไม่หักส่วน",
    "充值订单": "ออเดอร์เติม",
