    "钱包余额为负（因退款/拒付），充值抵平后才能继续使用。": "ยอดกระเป๋าติดลบ (จากคืนเงิน/ปฏิเสธจ่าย) ต้องเติมให้เท่าก่อนใช้ต่อ",
    "付款收据由 Stripe 作为收款商户出具，不是香港公司税票。": "ใบเสร็จชำระเงินออกโดย Stripe ในฐานะร้านค้าผู้รับเงิน ไม่ใช่ใบกำกับภาษีบริษัทฮ่องกง",
    "保存发票抬头后，可对已支付订单申请开票；真正的数电票由公司在电子税务局开出，申请当下不会得到税票文件。": "บันทึกชื่อออกใบกำกับแล้ว จึงขอใบกำกับจากออเดอร์ที่จ่ายแล้วได้ ใบกำกับอิเล็กทรอนิกส์จริงบริษัทออกที่หน่วยงานภาษีอิเล็กทรอนิกส์ คำขอตอนนั้นยังไม่ได้ไฟล์",
    "充值后你可以使用": "หลังเติมคุณใช้ได้",
    "按官方价按量计费，不加价": "ราคาโมเดลทางการ คิดตามปริมาณที่ใช้ ไม่บวก",
    "余额是真钱，不过期、不按月作废": "ยอดเป็นเงินจริง ไม่หมดอายุ ไม่ยกเลิกสิ้นเดือน",
    "一次充值，全站所有编辑器通用": "เติมครั้งเดียว ใช้ได้ทุกตัวแก้ไข OceanLeo",
    "数百个模型，按每次真实用量扣费": "หลายร้อยโมเดล หักตามปริมาณใช้จริงแต่ละครั้ง",
    "60 天内可自助退还未用完的余额": "ภายใน 60 วันหลังเติม คืนเองได้สำหรับยอดที่ยังไม่ใช้หมด",
    "一次余额，OceanLeo 系列网站通用": "ยอดเดียวใช้ได้กับทุกเว็บไซต์ในตระกูล OceanLeo",
    "这笔充值有拒付正在处理。剩余余额已冻结，暂停充值（{until}）。向发卡行撤回后会自动恢复。": "ยอดเติมนี้มี chargeback กำลังพิจารณา ยอดคงเหลือถูกแช่และเติมเงินถูกหยุด ({until}) หากถอนคำร้องที่ธนาคารผู้ออกบัตร ระบบจะคืนสถานะให้อัตโนมัติ",
    "发卡行已裁定这笔拒付成立。暂停充值至 {until}。剩余余额已解冻，可以继续使用。": "ธนาคารตัดสิน chargeback นี้ให้ฝั่งคุณ เติมเงินหยุดถึง {until} ยอดคงเหลือถูกปลดแล้วใช้ต่อได้",
    "近几笔充值几乎未使用就全额退款。暂停充值至 {until}。退款和余额不受影响。": "การเติมล่าสุดถูกคืนเต็มจำนวนทั้งที่แทบไม่ได้ใช้ เติมเงินหยุดถึง {until} การคืนเงินและยอดคงเหลือไม่เปลี่ยน",
    "近 {window} 天内有 {n} 笔充值几乎未使用就全额退款。暂停充值至 {until}。退款和余额不受影响。": "ใน {window} วันที่ผ่านมา มี {n} รายการถูกคืนเต็มจำนวนทั้งที่แทบไม่ได้ใช้ เติมเงินหยุดถึง {until} การคืนเงินและยอดคงเหลือไม่เปลี่ยน",
    "近 {window} 天内有 {n} 笔充值几乎未使用就全额退款。还能充值的次数已用完，暂停充值至 {until}。": "ใน {window} วันที่ผ่านมา มี {n} รายการถูกคืนเต็มจำนวนทั้งที่แทบไม่ได้ใช้ ใช้สิทธิ์เติมที่เหลือแล้ว จึงหยุดถึง {until}",
    "近 {window} 天内有 {n} 笔充值几乎未使用就全额退款，接下来至 {until} 还能充值 {left} 次。": "ใน {window} วันที่ผ่านมา มี {n} รายการถูกคืนเต็มจำนวนทั้งที่แทบไม่ได้ใช้ จนถึง {until} ยังเติมได้อีก {left} ครั้ง",
    "告诉我们哪里没做好": "บอกเราว่าตรงไหนยังไม่ดี",
    "拒付处理中：剩余余额已冻结，暂停充值。向发卡行撤回后，结案会自动恢复。": "กำลังพิจารณา chargeback: ยอดคงเหลือถูกแช่ เติมเงินหยุด หากถอนที่ธนาคาร เมื่อปิดเคสจะกลับมาอัตโนมัติ",
    "你上次付款用的卡暂不能用于充值（至 {until}），请换一张卡": "บัตรที่ใช้ชำระล่าสุดใช้เติมเงินไม่ได้จนถึง {until} กรุณาใช้บัตรอื่น",
    "你上次付款用的卡暂不能用于充值（不再可用），请换一张卡": "บัตรที่ใช้ชำระล่าสุดใช้เติมเงินไม่ได้อีก กรุณาใช้บัตรอื่น",
    "已原路全额退回（这张卡/账号暂不能充值）": "คืนเต็มจำนวนทางเดิมแล้ว (บัตร/บัญชีนี้ยังเติมเงินไม่ได้ชั่วคราว)",
    "因近期拒付被裁定为我们胜诉，{days} 天内按新账号额度充值，至 {until}。": "หลัง chargeback ที่เราชนะ คุณเติมด้วยเพดานบัญชีใหม่ {days} วัน จนถึง {until}",
    "结案前": "ก่อนปิดเคส",
    "不再可用": "ใช้ไม่ได้อีก",
