    "这笔充值有拒付正在处理。剩余余额已冻结，暂停充值（{until}）。向发卡行撤回后会自动恢复。": "इस टॉप-अप पर चार्जबैक चल रहा है। बचा बैलेंस रोक दिया गया है और टॉप-अप रुका है ({until})। जारीकर्ता बैंक से वापस लेने पर यह अपने आप बहाल होगा।",
    "发卡行已裁定这笔拒付成立。暂停充值至 {until}。剩余余额已解冻，可以继续使用。": "कार्ड बैंक ने यह चार्जबैक हमारे विरुद्ध तय किया। टॉप-अप {until} तक रुका रहेगा। बचा बैलेंस खुल गया है, आप उसे इस्तेमाल कर सकते हैं।",
    "近几笔充值几乎未使用就全额退款。暂停充值至 {until}。退款和余额不受影响。": "हाल के टॉप-अप लगभग बिना इस्तेमाल पूरे रिफंड हो गए। टॉप-अप {until} तक रुका है। रिफंड और बैलेंस नहीं बदलते।",
    "近 {window} 天内有 {n} 笔充值几乎未使用就全额退款。暂停充值至 {until}。退款和余额不受影响。": "पिछले {window} दिनों में {n} टॉप-अप लगभग बिना इस्तेमाल पूरे रिफंड हुए। टॉप-अप {until} तक रुका है। रिफंड और बैलेंस नहीं बदलते।",
    "近 {window} 天内有 {n} 笔充值几乎未使用就全额退款。还能充值的次数已用完，暂停充值至 {until}。": "पिछले {window} दिनों में {n} टॉप-अप लगभग बिना इस्तेमाल पूरे रिफंड हुए। बचा टॉप-अप इस्तेमाल हो चुका है, इसलिए {until} तक रुका है।",
    "近 {window} 天内有 {n} 笔充值几乎未使用就全额退款，接下来至 {until} 还能充值 {left} 次。": "पिछले {window} दिनों में {n} टॉप-अप लगभग बिना इस्तेमाल पूरे रिफंड हुए। {until} तक आप अभी {left} बार और टॉप-अप कर सकते हैं।",
    "告诉我们哪里没做好": "बताएँ हमने क्या ठीक नहीं किया",
    "拒付处理中：剩余余额已冻结，暂停充值。向发卡行撤回后，结案会自动恢复。": "चार्जबैक चल रहा है: बचा बैलेंस रोका गया, टॉप-अप रुका। बैंक से वापस लें तो केस बंद होने पर सब बहाल होगा।",
    "你上次付款用的卡暂不能用于充值（至 {until}），请换一张卡": "पिछली बार जिस कार्ड से भुगतान किया वह {until} तक टॉप-अप के लिए नहीं चल सकता। दूसरा कार्ड इस्तेमाल करें।",
    "你上次付款用的卡暂不能用于充值（不再可用），请换一张卡": "पिछली बार जिस कार्ड से भुगतान किया वह अब टॉप-अप के लिए नहीं चल सकता। दूसरा कार्ड इस्तेमाल करें।",
    "已原路全额退回（这张卡/账号暂不能充值）": "मूल रास्ते से पूरा रिफंड (यह कार्ड/खाता अभी टॉप-अप नहीं कर सकता)",
    "因近期拒付被裁定为我们胜诉，{days} 天内按新账号额度充值，至 {until}。": "हमारे पक्ष में तय चार्जबैक के बाद आप {days} दिन नए खाते की सीमा से टॉप-अप करते हैं, {until} तक।",
    "结案前": "केस बंद होने तक",
    "不再可用": "अब उपलब्ध नहीं",
